import json, os
from anthropic import Anthropic

cliente = Anthropic(api_key=os.environ["ANTHROPIC_API_KEY"])

ESQUEMA = {
    "name": "clasificacion",
    "input_schema": {
        "type": "object",
        "properties": {
            "categoria": {"type": "string"},
            "urgencia": {"type": "string", "enum": ["alta", "media", "baja"]},
            "datos": {"type": "object"},
            "confianza": {"type": "number"},
            "motivo": {"type": "string"},
        },
        "required": ["categoria", "urgencia", "confianza", "motivo"],
    },
}

def clasificar(texto: str, categorias: list[str]) -> dict:
    respuesta = cliente.messages.create(
        model="claude-haiku-4-5-20251001",
        max_tokens=700,
        tools=[ESQUEMA],
        tool_choice={"type": "tool", "name": "clasificacion"},
        messages=[{
            "role": "user",
            "content": (
                "Clasifica este caso en una de estas categorias: "
                + ", ".join(categorias)
                + ". Si ninguna encaja, usa 'otros' y baja la confianza.\n\n"
                + texto
            ),
        }],
    )
    for bloque in respuesta.content:
        if bloque.type == "tool_use":
            return bloque.input
    raise ValueError("el modelo no devolvio la herramienta")

