// Saca el JSON de la respuesta del modelo sin fiarse de que venga limpio.
const salida = [];
for (const item of $input.all()) {
  const caso = $('Validar').first().json;
  let bruto = item.json?.content?.[0]?.text ?? '';
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let datos;
  try {
    datos = JSON.parse(bruto);
  } catch (error) {
    datos = { categoria: 'otros', urgencia: 'media', datos: {}, confianza: 0, motivo: 'respuesta no parseable: ' + bruto.slice(0, 200) };
  }
  salida.push({
    json: {
      ...caso,
      categoria: datos.categoria ?? 'otros',
      urgencia: datos.urgencia ?? 'media',
      confianza: Number(datos.confianza ?? 0),
      motivo: datos.motivo ?? '',
      datos: JSON.stringify(datos.datos ?? {}),
      estado: 'clasificado',
    },
  });
}
return salida;

